import 'news_list/widgets/news_card.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<List<CurrencyModel>> _currenciesFuture;
  late Future<List<NewsModel>> _newsFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final CurrencyRepository currencyRepo = context.read<CurrencyRepository>();
    final NewsRepository newsRepo = context.read<NewsRepository>();

    _currenciesFuture = currencyRepo.fetchRates(
      const CurrencyPageRequest(base: 'USD', page: 0, pageSize: 20),
    ).then((CurrencyPage page) => page.items);

    _newsFuture = newsRepo.loadNewsFeed(const NewsFeedFilter());
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;
    final ThemeFonts fonts = context.fonts;
    final ThemeColors colors = context.colors;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<void>(
        future: _buildDataFuture(),
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          if (snapshot.hasError) {
            return Center(
              child: Text(
                '${loc.news}: ${snapshot.error}',
                style: fonts.regular14,
                textAlign: TextAlign.center,
              ),
            );
          }

          final List<CurrencyModel> currencies = snapshot.data!.$1;
          final List<NewsModel> news = snapshot.data!.$2;

          return SingleChildScrollView(
            padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  loc.currencyRate,
                  style: fonts.semiBold16,
                ),
                const SizedBox(height: 8),
                if (currencies.isEmpty)
                  Text(
                    'No data',
                    style: fonts.regular14.copyWith(color: colors.tin),
                  )
                else
                  ...currencies.take(5).map((CurrencyModel currency) {
                    return Padding(
                      padding: const EdgeInsets.only(bottom: 8),
                      child: _CurrencyRow(model: currency, fonts: fonts, colors: colors),
                    );
                  }),
                const SizedBox(height: 24),
                Text(
                  loc.news,
                  style: fonts.semiBold16,
                ),
                const SizedBox(height: 8),
                if (news.isEmpty)
                  Text(
                    'No data',
                    style: fonts.regular14.copyWith(color: colors.tin),
                  )
                else
                  ...news.take(5).map((NewsModel newsItem) {
